    kv_cache_config: KVCacheConfig,
    ...
) -> dict[str, torch.Tensor]:
    """Allocate SFA KV caches with decoupled indexer cache."""
    kv_caches = {}
    has_sfa_indexer_cache = self._check_indexer_cache()

    for layer_name, cache_spec in kv_cache_config.items():
